import{_ as t}from"./chunks/collection-grid.JG5zeoci.js";import{_ as a,a as o,b as i,c as s,d as n}from"./chunks/dark-theme.DwSjXCKk.js";import{_ as r,o as d,c as h,a5 as l}from"./chunks/framework.-jms6n7v.js";const T=JSON.parse('{"title":"DaruDB Studio","description":"DaruDB Studio is a desktop app for Windows, macOS and Linux that opens a DaruDB file and shows its collections, objects and schema, and lets you change them…","frontmatter":{"title":"DaruDB Studio","order":15,"prev":{"text":"Errors","link":"/guide/errors"},"next":{"text":"How the engine is built","link":"/engine/architecture"}},"headers":[{"level":2,"title":"Download","slug":"download","link":"#download","children":[]},{"level":2,"title":"Open a file","slug":"open-a-file","link":"#open-a-file","children":[]},{"level":2,"title":"Browse and edit objects","slug":"browse-and-edit-objects","link":"#browse-and-edit-objects","children":[]},{"level":2,"title":"Run queries","slug":"run-queries","link":"#run-queries","children":[]},{"level":2,"title":"The schema","slug":"the-schema","link":"#the-schema","children":[]},{"level":2,"title":"Tools","slug":"tools","link":"#tools","children":[]},{"level":2,"title":"Tabs, windows and themes","slug":"tabs-windows-and-themes","link":"#tabs-windows-and-themes","children":[]}],"relativePath":"guide/studio.md","filePath":"en/guide/studio.md","lastUpdated":1794204468000}'),c={name:"guide/studio.md"};function p(u,e,m,f,b,g){return d(),h("div",null,[...e[0]||(e[0]=[l('<h1 id="darudb-studio" tabindex="-1">DaruDB Studio <a class="header-anchor" href="#darudb-studio" aria-label="Permalink to &quot;DaruDB Studio&quot;">​</a></h1><p>DaruDB Studio is a desktop app for Windows, macOS and Linux that opens a DaruDB file and shows its collections, objects and schema, and lets you change them without writing a program to do it.</p><img src="'+t+'" alt="DaruDB Studio with the sample shop database open: the collections and the fields of products in the sidebar, and the products in a grid" width="1280" height="800"><p>The app reads the schema from the file itself, so it opens a file whichever language wrote it. It reads and writes through the Node.js package, which is the same engine every package uses, so what it shows is what your program reads.</p><h2 id="download" tabindex="-1">Download <a class="header-anchor" href="#download" aria-label="Permalink to &quot;Download&quot;">​</a></h2><p>The installers are on the <a href="https://github.com/jooy2/darudb-studio/releases" target="_blank" rel="noreferrer">Releases page</a> of the <a href="https://github.com/jooy2/darudb-studio" target="_blank" rel="noreferrer"><code>darudb-studio</code> repository</a>.</p><table tabindex="0"><thead><tr><th>System</th><th>What to download</th></tr></thead><tbody><tr><td>Windows</td><td>The installer (<code>.exe</code>), the portable app, a <code>.zip</code>, or the <code>.appx</code> package, x64</td></tr><tr><td>macOS</td><td>The <code>.dmg</code> for Apple silicon, for Intel, or the universal one for both</td></tr><tr><td>Linux</td><td>The <code>.deb</code>, <code>.rpm</code> or <code>.snap</code> package, x64</td></tr></tbody></table><p>The source is in the same repository, under the MIT license, and bug reports and feature requests go to its <a href="https://github.com/jooy2/darudb-studio/issues" target="_blank" rel="noreferrer">issues</a>.</p><h2 id="open-a-file" tabindex="-1">Open a file <a class="header-anchor" href="#open-a-file" aria-label="Permalink to &quot;Open a file&quot;">​</a></h2><p>The app keeps each file you open as a project: a name for the file, where it is, and, if you ask, its encryption key, which the operating system&#39;s keystore keeps encrypted. A file of any extension can be picked, and the app checks that it is a DaruDB database before keeping it.</p><ul><li>An encrypted file asks for its key when the project remembers none, or when the one it remembers no longer opens the file.</li><li>A file in an older format version is opened on a copy the app raises to the current version, or raised in place, as you choose. <a href="./../engine/file-format#format-versions">Format versions</a> says what raising a file means.</li><li>The project list also opens a sample database of a small shop, with every kind of field in it, to try the app on without a file of your own. Each sample is a new file in the app&#39;s own folder, deleted when the app quits.</li></ul><h2 id="browse-and-edit-objects" tabindex="-1">Browse and edit objects <a class="header-anchor" href="#browse-and-edit-objects" aria-label="Permalink to &quot;Browse and edit objects&quot;">​</a></h2><p>Each collection opens in a tab, as a grid that reads its objects a page at a time, so a large collection scrolls as fast as a small one. Columns sort and resize, the filter above the grid takes the <a href="./query-language">query language</a>, and values are colored by type. Lists and embedded objects expand in place, and a link shows the key of the object it points to.</p><p>A field of one value is edited in its cell, as in a spreadsheet. The whole object is edited in a dialog, where a list or an embedded object is a form of its items and fields, or JSON, whichever is easier for the change. A date is shown and typed as RFC 3339 text in UTC.</p><img src="'+a+'" alt="The dialog that edits a product, with its list of tags and its embedded size as forms" width="1280" height="800" loading="lazy"><p>An edit is written to the file as soon as you make it, or held until you submit every held edit from the toolbar, as the settings say. Held edits can be discarded until then.</p><h2 id="run-queries" tabindex="-1">Run queries <a class="header-anchor" href="#run-queries" aria-label="Permalink to &quot;Run queries&quot;">​</a></h2><p>A query tab runs a query written whole in the query language, <code>SORT BY</code> and <code>LIMIT</code> included, and shows the objects it finds in a grid that edits them as a collection&#39;s tab does.</p><img src="'+o+'" alt="A query tab that finds the delivered orders of 500 or more, sorted by their total" width="1280" height="800" loading="lazy"><p>The <code>Database</code> menu exports what a tab shows, or only its selected rows, to CSV or JSON, and imports objects from either into a collection, adding them or replacing the objects with the same key. An import is written in one transaction, so a file with one object that does not fit the collection imports nothing.</p><h2 id="the-schema" tabindex="-1">The schema <a class="header-anchor" href="#the-schema" aria-label="Permalink to &quot;The schema&quot;">​</a></h2><p>The sidebar lists the collections in the file, with how many objects each holds, and under each its key, its fields and their types, and its indexes. The schema opens in a dialog as the TypeScript the Node.js package declares it with, or as JSON, to copy into a program or save to a file.</p><img src="'+i+'" alt="The schema of the sample database shown as the TypeScript that declares it" width="1280" height="800" loading="lazy"><p>Collections and their fields are added, renamed and deleted from the sidebar. Each change is a migration the engine runs, and it raises the schema version stored in the file by one, with a backup of the file first if you ask for one.</p><div class="warning custom-block"><p class="custom-block-title">A program that declares the old version stops opening the file</p><p>After a schema change in the app, the file&#39;s schema version is newer than the one your program declares, and opening it fails with <code>SCHEMA_TOO_NEW</code>. Declare the new version, and the same collections and fields, in the program before it opens the file again. <a href="./migrations#several-versions-at-once">Several versions at once</a> has the rule.</p></div><h2 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to &quot;Tools&quot;">​</a></h2><p>The tools tab does what the <a href="./tools">tools</a> of the packages do, on the open file: it checks its integrity, compacts it, and writes a backup, encrypted with a key of its own if you ask. It also changes the key of an encrypted file.</p><img src="'+s+'" alt="The tools tab after an integrity check that found no problems and a compaction" width="1280" height="800" loading="lazy"><p>A damaged file is rescued into a new file that holds every object it can still give, which the app adds as a project of its own. The rescue is offered in the tools tab, and when a file fails to open because of the damage. The damaged file itself stays as it is.</p><h2 id="tabs-windows-and-themes" tabindex="-1">Tabs, windows and themes <a class="header-anchor" href="#tabs-windows-and-themes" aria-label="Permalink to &quot;Tabs, windows and themes&quot;">​</a></h2><p>Tabs split into groups side by side, move between them and merge again. Each window opens one project, and starting the app again opens another window in the app already running. When the settings ask, the app opens the windows, projects and tabs it had open when it last quit.</p><img src="'+n+'" alt="The products and the shipped orders in two tab groups side by side, in the dark theme" width="1280" height="800" loading="lazy"><p>The app is in English, German, French, Japanese and Korean, with a light and a dark theme. Both follow the system until the settings pick one.</p>',33)])])}const _=r(c,[["render",p]]);export{T as __pageData,_ as default};
